function formatDateWIB(date) {
  const wib = new Date(date.getTime() + (7 * 60 * 60 * 1000));
  const days   = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
  const months = ['Januari','Februari','Maret','April','Mei','Juni',
                  'Juli','Agustus','September','Oktober','November','Desember'];
  return `${days[wib.getUTCDay()]}, ${wib.getUTCDate()} ${months[wib.getUTCMonth()]} ${wib.getUTCFullYear()}`;
}

// ======================
// HELPER: bersihin BOM (U+FEFF) dari string apa pun
// ======================
function stripBOM(str) {
  if (typeof str !== 'string') return str;
  return str.replace(/^\uFEFF/, '').trim();
}

const result = {};
for (const [key, value] of Object.entries($json)) {
  if (
    typeof value === "object" &&
    value !== null &&
    value.label &&
    value.value !== undefined
  ) {
    const cleanLabel = stripBOM(value.label);
    result[cleanLabel] = value.value;
  }
}

result.submission_id = $json.id;
result.submitted_at = $json.createdAt;
result.submitted_at_display = formatDateWIB(new Date(result.submitted_at));

return [{ json: result }];

