=<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  @page {
    size: A4 landscape;
    margin: 0;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    width: 1122px;
    height: 794px;
    font-family: 'Segoe UI', Arial, sans-serif;
    background: #f0f4ff;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
  }
  .cert-wrap {
    width: 1082px;
    height: 754px;
    position: relative;
    background: #ffffff;
    border: 3px solid #1a3a6b;
    overflow: hidden;
  }

  /* Dekorasi sudut biru kiri bawah */
  .deco-bl {
    position: absolute;
    bottom: 0; left: 0;
    width: 220px; height: 300px;
    overflow: hidden;
    z-index: 0;
  }
  .deco-bl::before {
    content: '';
    position: absolute;
    bottom: -40px; left: -60px;
    width: 300px; height: 300px;
    background: #1565c0;
    transform: rotate(-30deg);
    transform-origin: bottom left;
  }
  .deco-bl::after {
    content: '';
    position: absolute;
    bottom: 30px; left: -20px;
    width: 200px; height: 200px;
    background: #42a5f5;
    transform: rotate(-20deg);
    transform-origin: bottom left;
    opacity: 0.7;
  }
  .deco-bl-light {
    position: absolute;
    bottom: 80px; left: 10px;
    width: 120px; height: 160px;
    background: #90caf9;
    transform: rotate(-25deg);
    transform-origin: bottom left;
    opacity: 0.5;
    z-index: 0;
  }

  /* Dekorasi sudut kanan atas */
  .deco-tr {
    position: absolute;
    top: 0; right: 0;
    width: 220px; height: 300px;
    overflow: hidden;
    z-index: 0;
  }
  .deco-tr::before {
    content: '';
    position: absolute;
    top: -40px; right: -60px;
    width: 300px; height: 300px;
    background: #1565c0;
    transform: rotate(-30deg);
    transform-origin: top right;
  }
  .deco-tr::after {
    content: '';
    position: absolute;
    top: 30px; right: -20px;
    width: 200px; height: 200px;
    background: #42a5f5;
    transform: rotate(-20deg);
    transform-origin: top right;
    opacity: 0.7;
  }
  .deco-tr-light {
    position: absolute;
    top: 80px; right: 10px;
    width: 120px; height: 160px;
    background: #90caf9;
    transform: rotate(-25deg);
    transform-origin: top right;
    opacity: 0.5;
    z-index: 0;
  }

  /* Border dalam */
  .inner-border {
    position: absolute;
    top: 16px; left: 16px;
    right: 16px; bottom: 16px;
    border: 1.5px solid #1a3a6b;
    z-index: 1;
    pointer-events: none;
  }

  /* Konten utama */
  .content {
    position: relative;
    z-index: 2;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px 120px;
    text-align: center;
  }

  .title {
    font-size: 56px;
    font-weight: 900;
    color: #1a3a6b;
    letter-spacing: 8px;
    text-transform: uppercase;
    margin-bottom: 4px;
  }
  .subtitle {
    font-size: 20px;
    font-weight: 600;
    color: #1a3a6b;
    letter-spacing: 6px;
    text-transform: uppercase;
    margin-bottom: 20px;
  }
  .given-to {
    font-size: 15px;
    color: #444;
    margin-bottom: 18px;
    font-style: italic;
  }
  .name-line {
    width: 420px;
    border-bottom: 2px solid #1a3a6b;
    margin: 0 auto 6px;
  }
  .recipient-name {
    font-size: 32px;
    font-weight: 700;
    color: #1a3a6b;
    margin-bottom: 6px;
  }
  .role-label {
    font-size: 14px;
    color: #555;
    margin-bottom: 4px;
  }
  .role-value {
    font-size: 24px;
    font-weight: 800;
    font-style: italic;
    color: #1a3a6b;
    letter-spacing: 2px;
    margin-bottom: 20px;
  }
  .desc {
    font-size: 13px;
    color: #444;
    line-height: 1.7;
    max-width: 560px;
    margin-bottom: 32px;
  }

  /* Bagian tanda tangan */
  .signatures {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0 20px;
  }
  .sig-block {
    text-align: center;
    width: 200px;
  }
  .sig-line {
    border-top: 2px solid #1a3a6b;
    margin-bottom: 6px;
  }
  .sig-name {
    font-size: 13px;
    font-weight: 700;
    color: #1a3a6b;
    letter-spacing: 1px;
  }
  .sig-title {
    font-size: 11px;
    color: #777;
  }

  /* Laurel icon tengah */
  .laurel {
    font-size: 48px;
    color: #c8922a;
  }

  /* Info skor & tanggal */
  .meta {
    font-size: 12px;
    color: #888;
    margin-top: 8px;
  }
</style>
</head>
<body>
<div class="cert-wrap">

  <!-- Decorations -->
