  <div class="deco-bl-light"></div>
  <div class="deco-tr"></div>
  <div class="deco-tr-light"></div>
  <div class="inner-border"></div>

  <!-- Content -->
  <div class="content">
    <div class="title">Certificate</div>
    <div class="subtitle">Of Achievement</div>
    <div class="given-to">Proudly presented to:</div>

    <div class="name-line"></div>
    <div class="recipient-name">{{ $('Get Employee').item.json.fields.full_name }}</div>

