    <div class="meta">
      Assignment ID: {{ $('Normalize Payload').item.json.assignment_id }} &nbsp;|&nbsp;
      Date: {{ $('Normalize Payload').item.json.submitted_at_display }}
    </div>
  </div>

</div>
